import { create } from './dom';

export const ICON_BASE = '/assets/icons';

export const ICONS = {
    activity: 'activity.svg',
    alerts: 'alerts.svg',
    back: 'back.svg',
    home: 'home.svg',
    favorites: 'favorites.svg',
    movies: 'movies.svg',
    tv: 'tv.svg',
    anime: 'anime.svg',
    animovies: 'animovie.svg',
    cartoons: 'cartoons.svg',
    client: 'devices.svg',
    controls: 'remote.svg',
    display: 'display.svg',
    download: 'download-cloud.svg',
    livetv: 'live-tv.svg',
    playlists: 'playlists.svg',
    collections: 'collections.svg',
    devices: 'devices.svg',
    dvr: 'dvr.svg',
    dashboard: 'dashboard.svg',
    metadata: 'metadata-manager.svg',
    paths: 'paths.svg',
    plugins: 'plugins.svg',
    reports: 'reports.svg',
    scheduled: 'scheduled-tasks.svg',
    settings: 'settings.svg',
    signout: 'signout.svg',
    subtitles: 'closed-caption.svg',
    profile: 'user.svg',
    search: 'search.svg',
    request: 'request.svg',
    server: 'server.svg',
    tasks: 'tasks.svg',
    transcoding: 'transcoding.svg',
    users: 'users.svg',
    play: 'play.svg',
    playback: 'playback.svg',
    pause: 'pause.svg',
    favorite: 'favorite.svg',
    played: 'check.svg'
};

export function iconUrl(name) {
    const file = ICONS[name] || name;

    if (!file) {
        return '';
    }

    if (file.startsWith('http') || file.startsWith('/')) {
        return file;
    }

    return `${ICON_BASE}/${file}`;
}

export function createIcon(name, className = 'ptv-icon') {
    return create('img', {
        className,
        attrs: {
            src: iconUrl(name),
            alt: '',
            loading: 'lazy',
            decoding: 'async',
            'aria-hidden': 'true'
        }
    });
}

export function iconNameFromText(text = '') {
    const key = String(text).toLowerCase().trim();

    if (key.includes('anime movie')) return 'animovies';
    if (key.includes('favorite')) return 'favorites';
    if (key.includes('movie')) return 'movies';
    if (key.includes('show') || key.includes('series')) return 'tv';
    if (key.includes('anime')) return 'anime';
    if (key.includes('cartoon')) return 'cartoons';
    if (key.includes('client')) return 'client';
    if (key.includes('display')) return 'display';
    if (key.includes('control') || key.includes('remote') || key.includes('keyboard')) return 'controls';
    if (key.includes('download')) return 'download';
    if (key.includes('live') || key.includes('guide')) return 'livetv';
    if (key.includes('playlist')) return 'playlists';
    if (key.includes('collection')) return 'collections';
    if (key.includes('dashboard')) return 'dashboard';
    if (key.includes('activity')) return 'activity';
    if (key.includes('alert')) return 'alerts';
    if (key.includes('device')) return 'devices';
    if (key.includes('dlna') || key.includes('live tv') || key.includes('dvr')) return 'dvr';
    if (key.includes('path')) return 'paths';
    if (key.includes('plugin')) return 'plugins';
    if (key.includes('report')) return 'reports';
    if (key.includes('scheduled') || key.includes('task')) return 'scheduled';
    if (key.includes('playback')) return 'playback';
    if (key.includes('transcoding')) return 'transcoding';
    if (key.includes('metadata')) return 'metadata';
    if (key.includes('quick connect')) return 'devices';
    if (key.includes('setting')) return 'settings';
    if (key.includes('sign') || key.includes('logout')) return 'signout';
    if (key.includes('subtitle') || key.includes('caption')) return 'subtitles';
    if (key.includes('profile')) return 'profile';
    if (key.includes('user')) return 'users';
    if (key.includes('search')) return 'search';
    if (key.includes('request')) return 'request';
    if (key.includes('server')) return 'server';
    if (key.includes('home')) return 'home';

    return '';
}
